slateY(-50%);border:0;border-radius:50%;width:42px;height:42px;background:#ffffffd9;color:var(--royal);font-size:2rem;line-height:1;cursor:pointer}.slide-prev{left:16px}.slide-next{right:16px}.dots{position:absolute;bottom:16px;left:0;right:0;text-align:center}.dot{width:9px;height:9px;border:0;border-radius:50%;margin:0 4px;background:#fff8;cursor:pointer}.dot.active{background:var(--gold);transform:scale(1.35)}.google-btn{display:block;text-align:center;padding:13px 18px;border:1px solid #cfcfcf;border-radius:9px;background:#fff;color:#303030;font-weight:700}.or{text-align:center;color:var(--muted);font-size:.85rem;margin:16px 0}.dashboard-welcome{display:flex;align-items:center;gap:24px;margin-bottom:28px}.admin-action{margin:18px 0}.admin-action summary{list-style:none}.admin-action summary::-webkit-details-marker{display:none}.trip-admin-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid #e8dfcb}.trip-poster{display:block;width:100%;max-height:420px;min-height:180px;object-fit:cover;border-radius:14px;margin:-4px 0 22px;border:0}.trip-poster-pdf{height:520px;background:#fff}.trip-poster-link{display:block}.trip-admin-row small{color:var(--muted);margin-left:6px}.btn.danger{background:#a44135;color:#fff}.dashboard-avatar{width:96px;height:96px;flex:0 0 96px;border-radius:50%;object-fit:cover;border:4px solid #fff;box-shadow:0 4px 18px #17382c33}.dashboard-initial{display:grid;place-items:center;background:var(--royal);color:#fff;font:700 2.8rem Fraunces}.avatar-picker{position:relative;width:128px;height:128px;margin:5px auto 4px}.avatar-picker .profile-avatar,.avatar-picker .profile-placeholder{width:128px;height:128px;margin:0}.camera-button{position:absolute;right:-2px;bottom:2px;width:42px;height:42px;display:grid;place-items:center;border:3px solid #fff;border-radius:50%;background:var(--gold);color:var(--ink);font-size:1.2rem;cursor:pointer;box-shadow:0 3px 12px #0003}.camera-button:hover{background:var(--royal);color:#fff}.photo-hint{text-align:center;color:var(--muted);font-size:.85rem;margin:0 0 22px}.visually-hidden{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}.profile-avatar,.profile-placeholder{width:110px;height:110px;border-radius:50%;object-fit:cover;margin:0 auto 22px;display:block}.profile-placeholder{display:grid;place-items:center;background:var(--royal);color:#fff;font:700 3rem Fraunces}@keyframes fade{from{opacity:.35}to{opacity:1}}@media(max-width:760px){.menu-toggle{display:block}.nav{padding:14px 18px;flex-wrap:wrap}.nav nav{display:none;width:100%;flex-direction:column;align-items:stretch;gap:3px;padding-top:8px}.nav nav.is-open{display:flex}.menu-checkbox:checked~nav[data-mobile-nav]{display:flex}.nav nav a{padding:10px 4px;border-bottom:1px solid #e8dfcb}.brand-logo{width:58px;height:58px}.hero{grid-template-columns:1fr;padding-top:25px}.hero-art,.gallery{min-height:280px}.gallery .slide,.gallery img,.about-gallery .slide,.about-gallery img{min-height:280px}.dashboard-welcome{align-items:flex-start}.grid,.stats,footer{grid-template-columns:1fr}nav{gap:11px;font-size:.8rem}.copyright{text-align:left}}
